{
  "outcome": "escalate",
  "rationale": "We are escalating this claim because automated findings raised a duplicate claim fraud flag, indicating the loss matches an earlier claim. Under policy section STD-7.2, duplicate claims must be referred to the special investigation unit.",
  "citations": [
    {
      "clause_id": "STD-7.2",
      "quote": "A claim for a loss that has already been reported to us, or paid, under this policy or any other policy, must be escalated to the special investigation unit."
    }
  ]
